using System;
using System.IO;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Effects;
using System.Windows.Media.Imaging;
using System.Windows.Media.Media3D;
using System.Windows.Shapes;

namespace LucyDesktop {
 public static class MotionPreviews {
  public static void Generate(string folder){Directory.CreateDirectory(folder);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var atlas=Sprites.Load("lucy-sprites.png");var frames=new BitmapSource[4];for(int i=0;i<4;i++)frames[i]=Sprites.Frame(atlas,i);var board=new Grid{Width=1000,Height=650,Background=UI.B("#F5EEFC")};board.RowDefinitions.Add(new RowDefinition{Height=new GridLength(65)});board.RowDefinitions.Add(new RowDefinition());var heading=new StackPanel{Margin=new Thickness(20,8,20,0)};heading.Children.Add(UI.Text("Lucy hareket seçenekleri",25));heading.Children.Add(UI.Text("Numaralı kısa örnekler · Otomatik hareketler seçim yapılana kadar kapalı",14,UI.Muted));board.Children.Add(heading);var grid=new System.Windows.Controls.Primitives.UniformGrid{Columns=3,Rows=2,Margin=new Thickness(8)};Grid.SetRow(grid,1);board.Children.Add(grid);var scenes=new MotionCard[6];string[] titles={"1 · Yürüme","2 · Zıplama ve sıçrama","3 · Kelebek kovalama","4 · Yuvarlanma","5 · Kutuya girip çıkma","6 · Yakınlaşma ve uzaklaşma"};string[] descriptions={"Sakin biçimde gidip başladığı yere döner.","Kısa bir yay çizip yere iner.","Küçük bir kelebeğin peşinden gider.","Kıvrılıp bir tur yuvarlanır.","Küçük kutuya girer, diğerinden çıkar.","Perspektifle küçülür, sonra yaklaşır."};for(int i=0;i<6;i++){var content=new StackPanel();var title=UI.Text(titles[i],19);title.FontWeight=FontWeights.SemiBold;content.Children.Add(title);scenes[i]=new MotionCard(i,frames);content.Children.Add(scenes[i]);var caption=UI.Text(descriptions[i],14,UI.Muted);caption.Margin=new Thickness(0,4,0,0);content.Children.Add(caption);grid.Children.Add(new Border{Background=UI.B("#FFFDFE"),BorderBrush=UI.B("#E6DAF0"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(16),Margin=new Thickness(7),Padding=new Thickness(12),Child=content});}var window=new Window{Width=1000,Height=650,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,ShowInTaskbar=false,ShowActivated=false,Left=-20000,Top=-20000,Content=board};window.Show();window.UpdateLayout();for(int f=0;f<48;f++){for(int i=0;i<6;i++)scenes[i].Draw(f/48.0);board.UpdateLayout();PetWindow.Snapshot(board,System.IO.Path.Combine(folder,"frame-"+f.ToString("000")+".png"),1000,650);}window.Close();app.Shutdown();}
 }
 class MotionCard:Canvas {
  int kind;BitmapSource[] frames;Viewport3D actor;ImageBrush texture;ScaleTransform3D scale;AxisAngleRotation3D yaw,roll;TranslateTransform3D depth;Ellipse shadow;Canvas butterfly;
  public MotionCard(int kind,BitmapSource[] frames){this.kind=kind;this.frames=frames;Width=280;Height=180;ClipToBounds=true;HorizontalAlignment=HorizontalAlignment.Center;shadow=new Ellipse{Width=65,Height=10,Fill=UI.B("#84718D"),Opacity=.18,Effect=new BlurEffect{Radius=3}};Children.Add(shadow);texture=new ImageBrush(frames[0]);var mesh=new MeshGeometry3D{Positions=new Point3DCollection{new Point3D(-1,-1,0),new Point3D(1,-1,0),new Point3D(1,1,0),new Point3D(-1,1,0)},TextureCoordinates=new PointCollection{new Point(0,1),new Point(1,1),new Point(1,0),new Point(0,0)},TriangleIndices=new Int32Collection{0,1,2,0,2,3}};var material=new DiffuseMaterial(texture);var model=new GeometryModel3D(mesh,material){BackMaterial=material};scale=new ScaleTransform3D();yaw=new AxisAngleRotation3D(new Vector3D(0,1,0),0);roll=new AxisAngleRotation3D(new Vector3D(0,0,1),0);depth=new TranslateTransform3D();var transforms=new Transform3DGroup();transforms.Children.Add(scale);transforms.Children.Add(new RotateTransform3D(roll));transforms.Children.Add(new RotateTransform3D(yaw));transforms.Children.Add(depth);model.Transform=transforms;var group=new Model3DGroup();group.Children.Add(new AmbientLight(Colors.White));group.Children.Add(model);actor=new Viewport3D{Width=145,Height=145,Camera=new PerspectiveCamera(new Point3D(0,0,3.8),new Vector3D(0,0,-1),new Vector3D(0,1,0),40)};actor.Children.Add(new ModelVisual3D{Content=group});if(kind==4){AddBox(85);AddBox(205);}Children.Add(actor);if(kind==2){butterfly=AdventureStage.MakeButterfly();butterfly.RenderTransformOrigin=new Point(.5,.5);Children.Add(butterfly);}Draw(0);}
  void AddBox(double x){var box=new Viewbox{Width=48,Height=48,Child=Box(),Stretch=Stretch.Fill};Canvas.SetLeft(box,x-24);Canvas.SetTop(box,109);Children.Add(box);}
  Canvas Box(){var c=new Canvas{Width=100,Height=90};c.Children.Add(new Polygon{Points=new PointCollection{new Point(5,18),new Point(25,4),new Point(94,16),new Point(75,31)},Fill=UI.B("#ECDDD2"),Stroke=UI.B("#9B8590"),StrokeThickness=2});c.Children.Add(new Polygon{Points=new PointCollection{new Point(75,31),new Point(94,16),new Point(94,72),new Point(75,85)},Fill=UI.B("#CAB3E1"),Stroke=UI.B("#9B8590"),StrokeThickness=2});var front=new Rectangle{Width=70,Height=54,Fill=UI.B("#D8C7E9"),Stroke=UI.B("#9B8590"),StrokeThickness=2};Canvas.SetLeft(front,5);Canvas.SetTop(front,31);c.Children.Add(front);var hole=new Ellipse{Width=50,Height=38,Fill=UI.B("#796387")};Canvas.SetLeft(hole,15);Canvas.SetTop(hole,39);c.Children.Add(hole);return c;}
  public void Draw(double u){double t=u<.5?AdventureMath.Smooth(u*2):1-AdventureMath.Smooth((u-.5)*2);double x=70+140*t,y=95,jump=0,size=1,z=0,angle=0,yangle=0,opacity=1;int frame=3;if(kind==1){if(u<.5)jump=Math.Sin(u*2*Math.PI)*40;frame=jump>4?1:3;}if(kind==2){x=140+55*Math.Sin(u*Math.PI*2);y=95+10*Math.Sin(u*Math.PI*4);double bx=x+25*Math.Cos(u*Math.PI*2);Canvas.SetLeft(butterfly,bx-20);Canvas.SetTop(butterfly,y-70);butterfly.RenderTransform=new ScaleTransform(.5+.5*Math.Abs(Math.Sin(u*Math.PI*20)),.7);jump=Math.Abs(Math.Sin(u*Math.PI*12))*3;}if(kind==3){frame=2;angle=-720*u;x=70+140*t;}if(kind==4){if(u<.25){x=55+30*AdventureMath.Smooth(u/.25);}else if(u<.40){double q=AdventureMath.Smooth((u-.25)/.15);x=85;y=95+30*q;size=1-.96*q;opacity=1-q;frame=0;}else if(u<.50){x=205;opacity=0;size=.04;}else if(u<.65){double q=AdventureMath.Smooth((u-.5)/.15);x=205;y=125-30*q;size=.04+.96*q;opacity=q;frame=1;}else x=205-150*AdventureMath.Smooth((u-.65)/.35);}if(kind==5){x=140;z=-3.2*Math.Sin(u*Math.PI);y=95-20*Math.Sin(u*Math.PI);yangle=15*Math.Sin(u*Math.PI);frame=0;}texture.ImageSource=frames[frame];texture.Opacity=opacity;scale.ScaleX=scale.ScaleY=scale.ScaleZ=size;roll.Angle=angle;yaw.Angle=yangle;depth.OffsetZ=z;Canvas.SetLeft(actor,x-72.5);Canvas.SetTop(actor,y-jump-72.5);double sw=65/(1+Math.Abs(z)*.15+jump/100);shadow.Width=sw;Canvas.SetLeft(shadow,x-sw/2);Canvas.SetTop(shadow,143);shadow.Opacity=.18*opacity/(1+jump/70);}
 }
}
